export type PythonLesson = {
  id: string; type: PythonLessonType; icon: string; xp: number; minutes: number; title: string; desc: string;
  level: PythonLevel; objectives: string[]; dax: { hint: string; explain: string; example: string };
  content?: string; keyPoints?: string[]; playground?: { starter: string; hint: string };
  prompt?: string; starter?: string; checks?: PythonCheck[]; solution?: string; questions?: PythonQuestion[];
};
export type PythonModule = { id: string; title: string; minutes: number; goal: string; level: PythonLevel; lessons: PythonLesson[] };

type ReadingSpec = { title: string; desc: string; analogy: string; code: string; note: string; hint: string };
