function daxFor(title: string, analogy: string, index: number) {
  return {
    hint: `Para ${title.toLowerCase()}, separa la entrada, la regla y el resultado; prueba también un caso límite.`,
    explain: `Imagínalo como ${analogy.toLowerCase()}: cada parte cumple una función y el resultado debe poder revisarse.`,
    example: `turno = "Turno ${index + 1}"\npaquetes = ${index + 2}\nprint(turno, paquetes)`,
  };
}

function escapeHtml(value: string) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function highlightPythonLine(line: string) {
  const escaped = escapeHtml(line);
  const keywords = new Set(["and", "as", "async", "await", "break", "class", "continue", "def", "elif", "else", "except", "finally", "for", "from", "if", "import", "in", "is", "lambda", "not", "or", "pass", "raise", "return", "try", "while", "with", "yield"]);
  const builtins = new Set(["abs", "bool", "dict", "filter", "float", "int", "len", "list", "map", "max", "min", "print", "range", "set", "sorted", "str", "sum", "tuple", "type"]);
  return escaped.replace(/(#.*$|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b[a-zA-Z_]\w*\b|\b\d+(?:\.\d+)?\b)/g, (token) => {
    if (token.startsWith("#")) return `<span class="cm">${token}</span>`;
    if (token.startsWith("\"") || token.startsWith("'")) return `<span class="st">${token}</span>`;
    if (keywords.has(token)) return `<span class="kw">${token}</span>`;
    if (builtins.has(token)) return `<span class="fn">${token}</span>`;
    if (/^\d/.test(token)) return `<span class="nm">${token}</span>`;
    return token;
  });
}

