function makeReading(module: ModuleSpec, spec: ReadingSpec, moduleIndex: number, lessonIndex: number): PythonLesson {
  const codeLines = spec.code.split("\n").map(highlightPythonLine).join("\n");
  const content = `<p>${spec.desc} ${module.goal}</p><h3>Una analogía</h3><p>${spec.analogy}</p><h3>Prueba este ejemplo</h3><pre class="code"><code>${codeLines}</code></pre><div class="note"><b>Atención:</b> ${spec.note}</div><h3>Forma de pensar</h3><ul><li>Nombrar los datos con claridad.</li><li>Comprobar qué resultado produce cada instrucción.</li><li>Explicar por qué la solución sirve en este contexto.</li></ul>`;
  return {
    id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "reading", icon: "📖", xp: 20, minutes: 10,
    title: spec.title, desc: spec.desc, level: module.level,
    objectives: [`Explicar ${spec.title.toLowerCase()} con tus palabras.`, "Predecir el resultado antes de ejecutar el ejemplo.", "Adaptar la idea a un caso profesional distinto."],
    dax: daxFor(spec.title, spec.analogy, moduleIndex * 10 + lessonIndex), content,
    keyPoints: [spec.desc, spec.note, `La capacidad se aplica a: ${module.goal.toLowerCase()}`],
    playground: { starter: spec.code, hint: spec.hint },
  };
}

function makeLab(module: ModuleSpec, spec: LabSpec, moduleIndex: number, lessonIndex: number): PythonLesson {
  const checkSet: PythonCheck[] = [
    { desc: "El código usa la estructura solicitada.", test: (code) => new RegExp(spec.pattern, "s").test(code) },
    { desc: "La salida del caso inicial es correcta.", test: (_code, context) => context.output.includes(spec.expected) },
    { desc: "La solución generaliza con datos alternativos.", test: async (code, _context, helpers) => {
      if (!code.includes(spec.replaceFrom)) return false;
      const alternate = await helpers.run(code.replace(spec.replaceFrom, spec.replaceTo));
      return !alternate.error && (spec.alternateExpected === "" ? alternate.output.length === 0 : alternate.output.includes(spec.alternateExpected));
    } },
  ];
  if (spec.behavior) checkSet.push({ desc: "El comportamiento del objeto o patrón coincide con el contrato.", test: (_code, context) => context.output.includes(spec.behavior ?? "") });
  if (moduleIndex === 19) {
    checkSet.push({ desc: "El cálculo auditado coincide con los datos JSON.", test: (_code, context) => context.output.includes("Auditado: 7") });
    checkSet.push({ desc: "El manifiesto identifica el paquete distribuible.", test: (_code, context) => context.output.includes("Paquete: gestor-ventas") });
  }
  checkSet.push({ desc: "El programa no produce errores.", test: (_code, context) => context.error === null });
  const moduleLabXp = module.level === "principiante" ? 50 : module.level === "intermedio" ? 60 : 80;
  const moduleLabMinutes = module.level === "principiante" ? 18 : module.level === "intermedio" ? 20 : 25;
  const isFinal = moduleIndex === 19;
  return {
    id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "lab", icon: isFinal ? "🚀" : "💻",
    xp: isFinal ? 200 : moduleLabXp, minutes: isFinal ? 45 : moduleLabMinutes,
    title: spec.title, desc: spec.desc, level: module.level,
    objectives: ["Implementar una solución que calcule resultados desde sus datos.", "Validar el comportamiento con más de un caso.", "Explicar una decisión de diseño y un límite de la solución."],
    dax: daxFor(spec.title, module.analogy, moduleIndex * 10 + lessonIndex),
    prompt: `<p>${spec.prompt}</p><p><strong>Criterio:</strong> el código debe calcular el resultado, no imprimir una respuesta fija.</p>`,
    starter: spec.starter, solution: spec.solution, checks: checkSet,
  };
}

function makeQuiz(module: ModuleSpec, spec: QuizSpec, moduleIndex: number, lessonIndex: number): PythonLesson {
  const rationale = quizRationales[moduleIndex];
  return {
    id: `m${moduleIndex + 1}l${lessonIndex + 1}`, type: "quiz", icon: "📝",
    xp: moduleIndex === 19 ? 100 : 60, minutes: moduleIndex === 19 ? 15 : 10,
    title: moduleIndex === 19 ? "Evaluación de integración" : `Decisiones sobre ${module.title.toLowerCase()}`,
    desc: `Comprueba tu criterio al aplicar ${module.title.toLowerCase()} en un problema real.`, level: module.level,
    objectives: ["Predecir una salida ejecutando mentalmente el código.", "Detectar un error frecuente antes de ejecutar.", "Justificar la opción que generaliza mejor."],
    dax: daxFor(module.title, module.analogy, moduleIndex * 10 + lessonIndex),
    questions: [
      { q: `¿Qué imprime este código?\n${spec.code}`, options: [spec.printed, "No imprime nada.", "Se produce un error de sintaxis.", "Imprime el nombre de la variable."], correct: 0, explain: `Sigue cada instrucción y evalúa los datos antes de elegir. El resultado es ${spec.printed}.` },
      { q: spec.mistake, options: [rationale.distractors[0], rationale.error, rationale.distractors[1], "El programa termina antes de evaluar la condición."], correct: 1, explain: rationale.error },
      { q: spec.reasoning, options: ["Porque evita toda validación.", rationale.distractors[1], rationale.reason, "Porque convierte todas las variables en texto."], correct: 2, explain: rationale.reason },
      { q: `¿Qué evidencia daría más confianza en una solución de ${module.title.toLowerCase()}?`, options: ["Probar solo el dato inicial.", "Ejecutar un caso nuevo y comprobar que conserva la regla esperada.", "Cambiar nombres hasta que parezca correcto.", "Ocultar los errores de ejecución."], correct: 1, explain: "Un caso nuevo ayuda a detectar respuestas fijadas y comprueba que la solución generaliza." },
    ],
  };
}

export const PYTHON_CURRICULUM: PythonModule[] = specs.map((spec, moduleIndex) => {
  const lessons: PythonLesson[] = [];
  spec.readings.forEach((reading, index) => lessons.push(makeReading(spec, reading, moduleIndex, lessons.length)));
  spec.labs.forEach((lab) => lessons.push(makeLab(spec, lab, moduleIndex, lessons.length)));
  lessons.push(makeQuiz(spec, spec.quiz, moduleIndex, lessons.length));
  return {
    id: `m${moduleIndex + 1}`, title: spec.title, level: spec.level, goal: spec.goal,
    minutes: lessons.reduce((total, lesson) => total + lesson.minutes, 0), lessons,
  };
});

export const MODULE_ICONS = ["🐍", "➕", "🔀", "🔁", "🧩", "🎛️", "✂️", "📋", "🗂️", "🛡️", "⚙️", "🏛️", "🧬", "⚡", "📦", "🌐", "🧪", "🚀", "🧠", "🏆"];

function validateCurriculum() {
  const readingCounts = [3, 2, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 0];
  const labCounts = [1, 1, 1, 2, 1, 2, 2, 2, 2, 2, 2, 2, 2, 1, 2, 2, 2, 2, 2, 1];
  if (PYTHON_CURRICULUM.length !== 20 || MODULE_ICONS.length !== 20) throw new Error("El currículo Python debe contener exactamente 20 módulos e iconos.");
  PYTHON_CURRICULUM.forEach((module, moduleIndex) => {
    const expectedLevel: PythonLevel = moduleIndex < 7 ? "principiante" : moduleIndex < 14 ? "intermedio" : "avanzado";
    const counts = module.lessons.reduce((total, lesson) => ({ ...total, [lesson.type]: total[lesson.type] + 1 }), { reading: 0, lab: 0, quiz: 0 });
    const moduleWordCount = module.title.trim().split(/\s+/).length;
    if (module.id !== `m${moduleIndex + 1}` || moduleWordCount < 3 || moduleWordCount > 7 || module.level !== expectedLevel || counts.reading !== readingCounts[moduleIndex] || counts.lab !== labCounts[moduleIndex] || counts.quiz !== 1) {
      throw new Error(`La estructura del módulo ${module.id} no coincide con el contrato del curso.`);
    }
    if (module.minutes !== module.lessons.reduce((sum, lesson) => sum + lesson.minutes, 0)) throw new Error(`La duración del módulo ${module.id} no coincide con sus actividades.`);
    module.lessons.forEach((lesson, lessonIndex) => {
      if (lesson.id !== `m${moduleIndex + 1}l${lessonIndex + 1}` || !lesson.title || lesson.title.trim().split(/\s+/).length > 7 || lesson.level !== module.level || lesson.objectives.length < 3 || !lesson.dax.hint || !lesson.dax.explain || !lesson.dax.example) {
        throw new Error(`La actividad ${lesson.id} tiene campos obligatorios incompletos.`);
      }
      if (lesson.type === "reading" && (!lesson.content || !lesson.keyPoints?.length || !lesson.playground)) throw new Error(`La lectura ${lesson.id} no tiene material interactivo completo.`);
      if (lesson.type === "lab") {
        if (!lesson.starter || !lesson.solution || !lesson.checks || lesson.checks.length < 4) throw new Error(`El laboratorio ${lesson.id} no tiene solución y pruebas completas.`);
        if (lesson.checks.some((check) => !check.desc || typeof check.test !== "function")) throw new Error(`El laboratorio ${lesson.id} tiene una prueba inválida.`);
        for (const check of lesson.checks) {
          if (check.desc.includes("estructura")) {
            try { new RegExp((specs[moduleIndex].labs[lessonIndex - readingCounts[moduleIndex]].pattern), "s"); }
            catch { throw new Error(`El laboratorio ${lesson.id} tiene una expresión estructural inválida.`); }
          }
        }
      }
      if (lesson.type === "quiz" && (!lesson.questions || lesson.questions.length < 3 || lesson.questions.some((question) => question.options.length !== 4 || question.correct < 0 || question.correct >= question.options.length))) {
        throw new Error(`El quiz ${lesson.id} tiene preguntas incompletas o mal formadas.`);
      }
    });
  });
}

validateCurriculum();

export function toPythonRunContext(result: PythonRunResult): PythonRunContext {
  return { output: [...result.output, ...result.stderr], vars: result.vars, error: result.error };
}